package io.lumine.mythic.lib.api.crafting.recipes; import io.lumine.mythic.lib.api.crafting.ingredients.*; import java.util.*; import java.util.concurrent.ConcurrentHashMap; public class MythicCachedResult { public static final String cacheNBTTagPath="MYTHICLIB_CRAFTING_CACHE"; private static final Map<UUID,MythicCachedResult> CACHE=new ConcurrentHashMap<>(); private final UUID id; private final MythicBlueprintInventory result; private final MythicRecipeBlueprint operation; private final MythicRecipeInventory display; private int times; public MythicCachedResult(UUID id,MythicBlueprintInventory result,MythicRecipeBlueprint op,MythicRecipeInventory display,int times){this.id=id;this.result=result;operation=op;this.display=display;this.times=times;CACHE.put(id,this);} public void unload(){CACHE.remove(id);} public UUID getOperationIdentifier(){return id;} public MythicBlueprintInventory getResultOfOperation(){return result;} public MythicRecipeBlueprint getOperation(){return operation;} public static MythicCachedResult get(UUID id){return CACHE.get(id);} public int getTimes(){return times;} public void setTimes(int t){times=t;} public MythicRecipeInventory getDisplay(){return display;} }
